/* From Uiverse.io by Yaseen549 - Tags: neumorphism, input */
.__UIV_SCOPE__ .input {
 border: none;
 border-radius: 15px;
 padding: 15px;
 background-color: #e8e8e8;
 box-shadow: 6px 6px 12px #ffffff,
             -6px -6px 12px #c5c5c5;
 font-size: medium;
 font-weight: bold;
 max-width: 200px;
}

.__UIV_SCOPE__ .input:focus {
 outline-color: white;
 place-content: "Enter your message!";
}
